            best=min(matches,key=lambda b:(abs(b['r0']-a['r0']),abs(b['c0']-a['c0'])))
            res.append((a,b,(best['r0']-a['r0'],best['c0']-a['c0'])))
        else:
            res.append((None,a,(None,None)))
    return res

